function buildInfectionStoryFrames(charId, fromPos, toPos){
 const d = CHAR[charId] || CHAR.lark;
 const story = INFECTION_STORIES[charId] || INFECTION_STORIES.lark;
 const coordStr = toPos ? xy(toPos.x, toPos.y) : '战区核心';
 const fromStr = fromPos ? xy(fromPos.x, fromPos.y) : '潜伏格';
 return [
  echoLine(charId, story.struggle, {
   side: 'g', camera: 'close', axis: 'left', kind: 'macro', sound: 'pulse',
   filmTitle: `⚡ 胸口寄生突发剧情 · ${d.name}`,
   caption: `${fromStr} 赤红蜘蛛扑击 ${coordStr} · 蜘蛛装置从棋盘消失并直接嵌入${d.name}胸口正中`,
   insert: {
    label: `PARASITE FUSION / 蜘蛛装置嵌入胸甲`,
    value: `${d.name} [${coordStr}]`,
    rows: [
     `来源：${fromStr} 赤红机械蜘蛛扑击成功`,
     `装置状态：棋盘上的赤蛛棋子已消失，直接融进${d.name}胸口正中央`,
     `神经状态：正义形态防线崩溃，正在转化为赤巢受控态`
    ]
   },
   focusCell: toPos ? [toPos.x, toPos.y] : null,
   markers: toPos ? [{x: toPos.x, y: toPos.y, badge: `⚡ 赤蛛装置融进胸口：${d.name}`, tone: 'red', from: fromPos ? [fromPos.x, fromPos.y] : undefined}] : []
  }),
  echoLine(charId, story.overmind, {
   overmind: true, side: 'r', camera: 'establish', axis: 'right', sound: 'pulse',
   filmTitle: `◈ 赤巢蛛皇 · 神经链路覆写`,
   caption: `赤巢最高领袖【赤巢蛛皇 · OVERMIND Ω】通过胸口红蜘蛛接管${d.name}的躯体`,
   focusCell: toPos ? [toPos.x, toPos.y] : null,
   markers: toPos ? [{x: toPos.x, y: toPos.y, badge: `◈ 蛛皇覆写：${d.name} 转为受控态`, tone: 'red'}] : []
  }),
  echoLine(charId, story.turned, {
   side: 'r', camera: 'close', axis: 'right', sound: 'knock',
   filmTitle: `◈ 永久受控觉醒 · ${d.name}（胸口红蜘蛛控制态）`,
   caption: `${d.name}双眸转为猩红，胸口正中红蜘蛛锁死（不可逆寄生 · 本阶段锁定）`,
   focusCell: toPos ? [toPos.x, toPos.y] : null,
   markers: toPos ? [{x: toPos.x, y: toPos.y, badge: `▲ 受控容器：${d.name} [${coordStr}]`, tone: 'red'}] : []
  })
 ];
}

/* Helper: Check whether a character is currently in Justice Form (side === 'g') */
function charCurrentSide(id){
 if(location.hash === '#qa') return C?.roster?.[id]?.side || CHAR[id]?.origin || 'g';
 const unit = S?.units?.find(u => u.char === id && !u.dead);
 if(unit) return unit.side;
 const rec = C?.roster?.[id];
 if(rec) return rec.side;
 return 'g';
}

/* Helper: Non-spoiler dynamic continuity summary from previous chapters */
function continuityLine(mid){
 const infectedList = Object.entries(C?.roster || {})
  .filter(([id, r]) => r.introduced && r.side === 'r' && r.status === 'active')
  .map(([id]) => CHAR[id]?.name).filter(Boolean);
 if(mid === 1){
  const fromBridge = C?.route === 'bridge';
  if(infectedList.length) return `【战情延续】：小队${fromBridge?'自轨道天桥转战':'突破 A–12 接驳甲板进入'}生态冷却环。上一战被赤蛛嵌入胸口的【${infectedList.join('、')}】已沦为赤巢蛛皇的受控容器，全员务必严防赤蛛近身！`;
  return `【战情延续】：小队${fromBridge?'自轨道天桥转战':'自 A–12 接驳甲板全员无损突入'} B–04 生态冷却环！目前所有机娘均保持【正义自主形态】，继续严防赤红蜘蛛扑击胸口！`;
 }
 if(mid === 2){
  const fromGarden = C?.route === 'garden';
  if(infectedList.length) return `【战情延续】：小队${fromGarden?'封死生态孵化池后':'突破接驳甲板后'}登上 C–07 轨道天桥。此前被胸口红蜘蛛寄生的【${infectedList.join('、')}】正随蛛群追击而来！`;
  return `【战情延续】：小队${fromGarden?'成功净化生态冷却环后':'自接驳甲板突围后'}全员保持【正义自主形态】登上 C–07 轨道天桥，死守方舟火控密钥！`;
 }
 if(mid === 3){
  if(infectedList.length) return `【战情延续】：跨越温室与天桥两条分支航线后，小队突入 D–00 中枢镜像库。已被赤蛛寄生的【${infectedList.join('、')}】正在镜室前方列阵阻截！`;
  return `【战情延续】：跨越温室与天桥分支航线后，全员以【正义自主形态】汇合于 D–00 中枢镜像库，准备解开中央电磁门！`;
 }
 if(mid === 4){
  if(infectedList.length) return `【终局战情延续】：中枢镜像破译完毕，小队正式杀入 Ω–00 母巢反应堆！面对盘踞在 E8 的【赤巢蛛皇】与曾被寄生的同伴【${infectedList.join('、')}】，决战打响！`;
  return `【终局战情延续】：中枢镜像破译完毕，十八名美少女机娘全员以【正义自主形态】杀入 Ω–00 母巢反应堆，直面盘踞在 E8 王座的最高领袖【赤巢蛛皇】！`;
 }
 return '';
}

